const idade = Number(query.idade);
const genero = (query.genero || "").toLowerCase();
const tempoContribuicao = Number(query.tempo_contribuicao);
const contribuiaAntesReforma = query.contribuia_antes_2019 === true;

function isMulher(g) {
  return g.startsWith("f");
}

const pontosNecessarios = isMulher(genero) ? 93 : 103;
const tempoMinContribuicao = isMulher(genero) ? 30 : 35;
const idadeMinProgressiva = isMulher(genero) ? 59.5 : 64.5;
const idadeMinGeral = isMulher(genero) ? 62 : 65;
const tempoMinGeral = isMulher(genero) ? 15 : 20;

let qualificado = false;
let regraAplicavel = null;
const motivos = [];

// Regra 1: Aposentadoria programada (regra geral)
if (idade >= idadeMinGeral && tempoContribuicao >= tempoMinGeral) {
  qualificado = true;
  regraAplicavel = "Aposentadoria programada (regra geral)";
  motivos.push(`Idade ${idade} >= ${idadeMinGeral} e contribuição ${tempoContribuicao} >= ${tempoMinGeral} anos`);
}

// Regra 2: Regra de pontos (transição)
if (!qualificado && contribuiaAntesReforma) {
  const pontos = idade + tempoContribuicao;
  if (pontos >= pontosNecessarios && tempoContribuicao >= tempoMinContribuicao) {
    qualificado = true;
    regraAplicavel = "Regra de pontos (transição)";
    motivos.push(`Pontos ${pontos} >= ${pontosNecessarios} e contribuição ${tempoContribuicao} >= ${tempoMinContribuicao} anos`);
  }
}

// Regra 3: Idade mínima progressiva (transição)
if (!qualificado && contribuiaAntesReforma) {
  if (idade >= idadeMinProgressiva && tempoContribuicao >= tempoMinContribuicao) {
    qualificado = true;
    regraAplicavel = "Idade mínima progressiva (transição)";
    motivos.push(`Idade ${idade} >= ${idadeMinProgressiva} e contribuição ${tempoContribuicao} >= ${tempoMinContribuicao} anos`);
  }
}

if (!qualificado) {
  motivos.push("Não atende aos requisitos mínimos identificados nas regras avaliadas.");
}

const resultado = {
  qualificado,
  regra_aplicavel: regraAplicavel,
  detalhes_avaliacao: motivos,
  aviso: "Esta é uma triagem automatizada preliminar, não substitui análise jurídica do Dr. Danilo."
};

return JSON.stringify(resultado);

