={{
(() => {
  const dataStr = $fromAI('data_inicio', 'Data e hora de início da consulta, em formato ISO 8601. Deve ser um dia útil entre segunda e quinta-feira, entre 09:00 e 17:00.', 'string');
  const start = new Date(dataStr);
  const diaSemana = start.getDay();
  const hora = start.getHours();

  if (diaSemana < 1 || diaSemana > 4) {
    throw new Error('Horário rejeitado: só é permitido agendar de segunda a quinta-feira.');
  }
  if (hora < 9 || hora >= 17) {
    throw new Error('Horário rejeitado: só é permitido agendar entre 09:00 e 17:00.');
  }

  const end = new Date(start);
  end.setHours(end.getHours() + 1);

  return JSON.stringify({
    summary: $fromAI('titulo_consulta', 'Título da consulta agendada', 'string'),
    start: { dateTime: start.toISOString(), timeZone: 'America/Sao_Paulo' },
    end: { dateTime: end.toISOString(), timeZone: 'America/Sao_Paulo' },
    attendees: [
      { email: $fromAI('email_lead', 'E-mail do lead coletado durante a conversa, usado para enviar o convite da consulta', 'string') },
      { email: 'filipovesrd@gmail.com' }
    ]
  });
})()
}}
